#include <vector>
#include <queue>
#include <unordered_set>

using namespace std;

class Solution {
public:
    int minFlips(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size(), start = 0;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                if (mat[i][j])
                    start |= 1 << (i * n + j);

        queue<pair<int, int>> q;
        unordered_set<int> visited;
        q.push({start, 0});
        visited.insert(start);

        vector<pair<int, int>> dirs = {{0,0},{0,1},{1,0},{0,-1},{-1,0}};

        while (!q.empty()) {
            auto [state, step] = q.front(); q.pop();
            if (state == 0) return step;

            for (int i = 0; i < m; ++i) {
                for (int j = 0; j < n; ++j) {
                    int next = state;
                    for (auto [dx, dy] : dirs) {
                        int x = i + dx, y = j + dy;
                        if (x >= 0 && y >= 0 && x < m && y < n) {
                            next ^= 1 << (x * n + y);
                        }
                    }
                    if (!visited.count(next)) {
                        visited.insert(next);
                        q.push({next, step + 1});
                    }
                }
            }
        }
        return -1;
    }
};
